INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p987483-phys101', 'stk-sec-ne', 'PHYS 101', 'info', '{"desc": "تحمست اكون اول واحد يقيم phys 101 لاني عارف\nانه راح يكون هناك ترهيب و تكريه في الماده ذي\n\nشباب انتوا راح تسمعوا كثير انها صعبة …\nو الصعوبة ما هي كامنة في صعوبة الماتريال\nلكنها في احتياج هالمادة للوقت الكافي لمذاكرتها\nفالزبدة انه اذا انك ماسك هالمادة اول باول … صدقني ما امزح معاك اذا قلت\nالايه بلس في هذي المادة جداااااااااااا سهل …\n\nطريقة المذاكرة : سلايدات الجلال و اذا هنق عليك شيء فيها ارجع للكتاب\nثم حل اغلب المسائل الي في اولد اقزام العبيد ( تلاقيها في الجمعية ) بشكل اسبوعي\nو الحياة سهالات 🤪", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/2", "user": "sec-ne", "ts": 1329379968000, "tid": 120502, "pn": 2}}', 1329379968000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p996965-phys101', 'stk-abo_ali', 'PHYS 101', 'info', '{"desc": "بسم الله\nفيزكس 101 الطبعه التاسعه (طبعا جزئين )\n\nجودة المقرر بشكل عام\nمن يوم عرفت الفيزياء ما حسيت ان لها داعي 😂\n\nالمواضيع التي يغطيها المقرر\nيغطي مواضيع واقعيه تقدر تشوفها وتحسها بنفسك\nمثل المتجهات والقوى وقوانين نيوتن والحركه الدايريه والحركه المستقيمه وغيرها\n\nالكتاب المستخدم للمقرر\nالكتاب كلامه وواجد وما تقدر تاخذ منه الزبده بسهوله\nلكن الزين فيه ان بعد كل شبتر بتعين ملخص سريع خفيف عن كل اللي اخذته والقوانين اللي تعلمتها في نفس الشابتر , وذي تنحسب لصالح الكتاب\n\nالأسئلة والأمثلة المستخدمة في المقرر\nالتشك بوينت كوسيه والسابمل بروبلم سهله وتطبيق مباشر , لكن عاد لمن يجيك التمارين , فيها المتوسط الصعب وفيها النااااار . لكن فوق ذا كله السليوشن مانيول ما راح يقصر وياك 🙂\n\nمدى فائدته في الناحية التطبيقية\n: (\n\nالزين في الكتاب هو الملخص اللي بعد كل شبتر والتشك بوينت\nغيرها كله حشو في حشو الله يسامحهم\nسلايدات الجلال هي المرجع الافضل 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/3", "user": "Abo_Ali", "ts": 1330547214000, "tid": 120502, "pn": 3}}', 1330547214000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1030370-phys101', 'stk-s2010xxxxx', 'PHYS 101', 'info', '{"desc": "سمعة الكورس هذا بالمادة مخيفه جدا … لا تهمك السمعه … لانك اذا ذاكرت اول باول راح تتفاجأ بدرجاتك وراح تشوف ان اغلب الكلام اللي تسمعه مجرد تحبيط لا اكثر ولا اقل … وانصح بنوت الجلال مع الاولد اكزام … وحاول تفهم الكونسبت لان الافكار دايم تتجدد بالاختبارات …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/4", "user": "s2010xxxxx", "ts": 1335740538000, "tid": 120502, "pn": 4}}', 1335740538000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1252741-phys101', 'stk-user8713', 'PHYS 101', 'info', '{"desc": "لعيون دفعة 2012\n\nحبيبي عآلي الطموح\n\nلا تقل أريد الحصول على A او A+\n\nبل قل أريد الحصول على A+ فقط و فقط و لن أقبل بغيرها\n\nإذا هذه الخطوة الأولى (العزم و الأصرار)\n\nمقولة أن الفيزياء صعب أضرب بها عرض الجدار\n\nالواجب حله بنفسك ثم تأكد من المنتدى\n\nPhysics 101 مادة ممتعة فلا تفوتك\n\nمسائل الكتاب مسائل الكتاب مسائل الكتاب مسائل الكتاب مسائل الكتاب\nProblems Problems Problems Problems Problems Problems\n\nطبعا أهم شيء للحصول على A+ حل مسائل الكتاب المسماة ب Problems\n\nوقبل ما تحلهم حل الأمثلة Sample problems\n\nعودا على بدء حبيبي عآلي الطموح أهم شيء مسائل الكتاب ما وصيك فيها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/10", "user": "user8713", "ts": 1376543400000, "tid": 120502, "pn": 10}}', 1376543400000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1314373-phys101', 'stk-medoalkebsi', 'PHYS 101', 'info', '{"desc": "<b>\n\nجودة المقرر بشكل عام: المقرر سهل وممتع\nالمواضيع التي يغطيها المقرر : يغطي المواضيع المتعلقه بالمكانكس\nالكتاب المستخدم للمقرر: بالنسبه لي آحب اقرى الكتب في كل المواد , لكن الفزكس من اسواء الكتب الي مرت علي بالجامعه, انصح الي يبغى يذاكر يروح يذاكر من كتاب جامعه الملك سعود…\n\nمدى فائدته في الناحية التطبيقية : انا توي مخلص الكورس وللان ما شفت شي من ناحيه تطبيقيه , الشي الوحيد انه صرت اعرف اكثر بالكورس وفاهم فيه اكثر من السابق .\n\nالسمعة : الصراحة الماده هذي كنت اسمع الشباب يقولوآ مره تخوف مدري كيف فيها مصايب والي يجي يقول لي : لاتدور اكثر من D … حسيت اني رايح معركه مو دراسه, والحمدلله الكورس والله سهل للي فهم الكونسبت حقه كويس , الكورس هذا يحتاج اساتذه عندهم اسلوب في توصيل المعلومه بشكل ممتاز…انا كنت عند مدرس الصراحه ما كنت افهم معه شي . مع ذلك الانترنت مايقصر معك\n\nاذا تبغى تجيب قريد كويس , افصل نفسك عن المحطمين الي حولك .\n\nوبالتوفيق للجميع… 🌹\n\n</b>", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/11", "user": "Medoalkebsi", "ts": 1388777211000, "tid": 120502, "pn": 11}}', 1388777211000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1316287-phys101', 'stk-abo-da7m', 'PHYS 101', 'info', '{"desc": "الفصل\n131\nجودة المقرر بشكل عام\nممتاز جدا\nالمواضيع التي يغطيها المقرر\nالحركة باتجاه واحد واتجاهيين - القوى - الطاقة وتحولاته - الحركة الدورانية والتوافقية البسيطة\nالكتاب المستخدم للمقرر\nجيد جدا إلى جيد، شرحه للمبادئ والقوانين موب واضح مرة بس جيد بشرح الأمثلة + اسئلة آخر الكتاب ممتازة جدا ومتنوعة\nالأسئلة والأمثلة المستخدمة في المقرر\n95% من اسئلة الاختبارات تجي من اسئلة الكتاب ( اللي بآخر كل باب ) مع تغيير أرقام + سؤالين أو 3 بكل اختبار تبع a و a+ ومعظم الباقي متوسط ومباشر\nمدى فائدته في الناحية التطبيقية\nمفيد جدا، لأنه يتكلم عن مبادئ أساسية وأولية\n\nإضافات\n\nبوجهة نظري :\n\n* المقرر مظلوم من الإشاعات اللي تجيه … صح فيه صعوبة لكن أقل بكثير مما يوصفوه الطلاب\n\n* الرسايل السلبية من الطلاب اللي سبق وأخذو المقرر لها دور كبير بانخفاض الدرجات فلا تسمع من أحد واحكم بنفسك\n\n* مفتاح الa و الa+ أسئلة الكتاااب على قدر ما تحل منهن على قدر ما تجاوب صح بالمياجر … نصيحة ذاكر أول بأول وحل أكبر قدر منهن ( السلوشن مانيول موجود بالمنتدى )", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/13", "user": "abo-da7m", "ts": 1389037016000, "tid": 120502, "pn": 13}}', 1389037016000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1372736-phys101', 'stk-user8581', 'PHYS 101', 'info', '{"desc": "جودة المقرر بشكل عام\nكورس حلو وسهل نوعا ما لكن الشعب الله يهديهم عاطينه اكبر من حجمه ومخلين انك تاخذ قريد عالي شيئ مستحيل … لولا تقصيري في الفاينل كان خذت قريد محترم لكن الحمدلله على كل حال\n\nالمواضيع التي يغطيها المقرر\nيتركز على مسائل الحركة وقوانين نيوتن بشكل كبير وفي النهاية عن الموائع ( fluids ) + الجاذبية … كماتيريال يعتبر سهل\n\nالكتاب المستخدم للمقرر & الأسئلة والأمثلة المستخدمة في المقرر\nكـ شرح اشوف في افضل منه لكن احسن شي فيه هو الملخص الي يكون نهاية الشابتر + الاسئلة اذا حليتها بفهم مب بس نظر للسلوشن مانول راح تاخذ قريد محترم\nتبي a+ حل اسئلة الكتاب بأنتظام يعني اول ماتاخذ الدرس حاول في الويكند تحل 10 اسئلة\nمن الي عليهم نقطتين و شوية اسئلة الي عليهم نقطة لأنهم يكونوا سهلين نوعا ما\nعشان تفهم طريقة الكتاب في الاسئلة والكونسبت\n\nفيه شيئ انتبه منه : وهو بعد الميجر الاول الي يكون سهل اذا خذت درجة حلوة لا تتراخى وتسحب على الفيزكس وتقول سهل لأنك بتاكلها في الميجر الثاني والثالث .\nحاول تبدع في المياجر واللاب عشان تدخل الفانيل بس عشان تضمن قريد حلو\n+\nمن 131 خلو فيه 3 مياجر كل واحد عليه 15 درجة\nو132 الغوا هوموركات الاونلاين وصار على الكويزات 10 درجات\n\nالزبدة : لاتعطيه اكبر من حجمه او تستهين فيه بسبب كلام الي حولك …ترا والله الفزكس خصوصا 101 مثل اي كورس لكن سمعته هي المخربة عليهوتخلي الطلاب مايذاكرون بس لأنهم يعتقدون ان مستواهم في المادة هو النجاح بس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/14", "user": "user8581", "ts": 1401212179000, "tid": 120502, "pn": 14}}', 1401212179000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1421435-phys101', 'stk-user10202', 'PHYS 101', 'info', '{"desc": "ترم ١٤١\nكورس ممتع، يتضمن قوانين السرعة والتسارع بالحركة المستقيمة والدائرية وقوانين نيوتن بالحركة المستقيمة والدائرية وحفظ الزخم والجاذبية والسكون وحفظ الطاقة الميكانيكية وتحولاتها والشغل والحركة المتناغمة وشوية من ميكانيكا الموائع.\nقارن نفسك قبل الكورس وبعده، راح تحس بالفرق.\nأغلب الناس يبدون يحلون المسائل قبل لا يفهمون الكونسبت كويس، وهذا اللي أشوفه مصعب عليهم الكورس.\nأحسن طريقة للمذاكرة إذا كان دكتورك مو كويس ـ مثلي ـ انك بعد نهاية كل تشابتر تقرأ الكتاب والنوته حقت الجلال، وإذا فيه شيئ ما قدرت تفهمه روح لليوتيوب، أنصحك بواحد رهيب اسمه van biezen.\nبعد ما تفهم الكونسبت كويس، حل أسئلة الكحيلي كللللها، كل تشبتر له أسئلة لحاله، راح تحصلها بموقعه.\nبالنسبة لأسئلة الكتاب راح تاخذ منك وقت كثير، السؤال الواحد تقريباً ٦ سطور وعلى بال ما تفهمه وتترجم اللي مو فاهمه وتحله الا راح من وقتك ربع ساعة، أما بأسئلة الكحيلي راح تلقى نفس السؤال ونفس الفكرة وما راح ياخذ منك ٣ دقايق، فأنا أنصح انك تسحب على أسئلة الكتاب إذا كنت بتحل حقت الكحيلي، وفالك A+ إن شاء الله.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/15", "user": "user10202", "ts": 1421954327000, "tid": 120502, "pn": 15}}', 1421954327000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1436413-phys101', 'stk-osamah56', 'PHYS 101', 'info', '{"desc": "ترم 151\n\nكورس ممتع ، والله اني كنت من اشد مبغضين الفيزيكس من ايام الثانوي لكن هذي المادة حببتني في الفيزيكس وصرت مهتم فيه .\n\nالمادة سهلة لكن مظلومة من الطلاب الي يراكمون الدروس ويذاكرون قبل الاختبار بيوم .\n\nاولد اكزام الكحيلي مصدر جيد للمذاكرة .\n\nوالله يوفق الجميع . 🌺", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/16", "user": "osamah56", "ts": 1450625946000, "tid": 120502, "pn": 16}}', 1450625946000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1439413-phys101', 'stk-user9534', 'PHYS 101', 'info', '{"desc": "ههههههههههههههه الكورس الفلم اللي أسمع عنه وأنا بالتحضيري 😆\nالزبدة الكورس صعيب برشا زي ماقالوا 😦 عموما ذاكر سلايدات الجلال واولد اكزام الكحيلي وان شاء الله أمورك تمشي 😎\nقسم الفزكس أغرب قسم شفته بحياتي , مايمديك تضمن شيء أبد 😠 أسئلة غريبة عجيبة 🙂\n\nأنت ذاكر وسو اللي عليك وأهم شيء تعدي وتعوض في الكورسات اللي قدام 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/17", "user": "user9534", "ts": 1453076279000, "tid": 120502, "pn": 17}}', 1453076279000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1466642-phys101', 'stk-user10578', 'PHYS 101', 'info', '{"desc": "161\n\nكورس غثيث و طويل ما خلصنا منه الا بطلعت الروح\nمواضيعه أظن درسناها بالثانوي ، تقدر تفهمها بالتأكيد لكن المشكلة باسئلة المياجر و هذه تحتاج الى براكتس\nالكورس ما هو مستحيل لو تشد حيلك فيه بتجيب على الاقل c او c+\nتوزيع الدرجات كان كالتالي بالصورة\nhttps://s27.postimg.org/sbtthlcmb/screenshot_235.jpg\n\nطريقة المذاكرة الافضل :\n1- سلايدات جلال\n2- فيديوهات البلاك بورد للدكاترة مكي و سالم و واثق البشير\n3- اذا فهمت السلايدات مو ضروري تمر على الفيديوهات فهي طويلة و تفصل بزيادة لكن انصحك تمر على فيديوهات د. واثق البشير وهي حل اسئلة وليست شرح\n4- اولد اقزام الكحيلي ( اهم شيء ) كل ما يحليت اكبر عدد ممكن من الاسئلة كل ما زاد فهمك .\n5- اخر شيء و اللي حل ازمة كبيرة للطلاب هذا الترم وهو فيديوهات اليويتيوب للاخ أنس ، أظن عنده موضوع مثبت بالمنتدى لحل اسئلة الكحيلي\nبصراحة جهد جبار و يشكر عليه ، قناته اسمها dafra zone ، المشكلة الوحيدة عندنا كانت وقت تنزيل الفيديو كان يتنزل اخر شابتر قبل الميجر بيوم او يومين\nلكن الان الفيديوهات لكل الشباتر موجودة بالبيوتيوب وهذا من حظ من سيأتي بعدنا .\n6- اخيراً لا فكر تذاكر من الكتاب او حتى تحل المسائل اللي فيه لان احياناً مسائله اصعب من اسئلة المياجر .\n\nاخيراً كل أساليب المذاكرة متوفرة عندك و الكرة في ملعبك و الباقي عليك .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/18", "user": "user10578", "ts": 1484905101000, "tid": 120502, "pn": 18}}', 1484905101000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1466746-phys101', 'stk-abdullah2015', 'PHYS 101', 'info', '{"desc": "ترم 161\n\nفيزكس 101 ما هو صعب بقد ما يحتاج متابعة أول أول\n\nيعني لو واحد حل كل أسئلة الكحيلي بفهم لكل التشابترات أول بأول + حل على الأقل 3 أولد إقزامات قبل المياجر والفاينل أضمن له ما لا يقل عن B+\n\nالسالفة وما فيها بقد ما تغطي أكبر عدد ممكن من الأفكار من الأولد إقزام وأسئلة الكحيلي بقد ما تجيب درجة عالية في المياجر والفاينل…\n\nإذا أهملت الكورس راح تلاقي إنه كورس غثيث وآخر الترم راح تدور النجاح بس … فانتبه إنك تراكم الدروس\n\nالميجر الأول (نسبيًا) أسهل من الميجر الثاني والثالث، انتبه إنك تضيعه من يدك\n\nأشوف إنه الA+ ممكنة، لكن راح تتطلب منك جهد عالي ومتابعة أول بأول زي ما ذكرت وما فيه شيء يجي بالساهل … فلكل مجتهد نصيب.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/19", "user": "Abdullah2015", "ts": 1485069964000, "tid": 120502, "pn": 19}}', 1485069964000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1485908-phys101', 'stk-hussin119', 'PHYS 101', 'info', '{"desc": "171\nكورس حلو وممتع بس يبي له شدة ومذاكرة شبه اول باول\nطريقة المذاكرة بالنسبة لي\nاكون فاهم الكونسبت سواء من المدرس او فيوهات البلاك بورد او اذا مستعجل اشوف المقدمة من دفرة زون\nاحل نص اسئلة الكحيلي اقل او اكثر حسب افكار التشابتر\nوقبل الميجراحل 2او 3 اولد اكزام وبس\n\nالميجر الاول اسهل من الثاني لاتهمل فيه\n\nاستغرب من بعض الطلاب الي يقولو القريد فيه مستحيل بدون مايذاكرو ياخي ذاكر **وحل ** بنفسك وتجيب ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/20", "user": "Hussin119", "ts": 1515581512000, "tid": 120502, "pn": 20}}', 1515581512000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1486106-phys101', 'stk-user10610', 'PHYS 101', 'info', '{"desc": "الحمد لله توني خلصت الكورس قبل أسبوعين …\nأكثر كورس بتسمع عنه في حياتك الجامعية, فيه كمية ترهيب وتخويف من الطلاب غير طبيعية وكأنه كورس جاي الدرك الأسفل . للناس اللي يحبون الحلطمه وأن جامعتنا أصعب جامعة أتوقع نواة التجمع حقتهم في هذا الكورس .\nبعد ما تسمي بالله وتبدأ ترتب أوراقك لبداية السمستر الجديد وبالذات اذا كنت منزل PHYS101 أبتعد واهرب واركض بعيدًا عن الناس المحطمين المتحلطمين . كل الشباب اللي كتبوا قبلي في هذا الموضوع اتفقوا بشبه إجماع على أن **(****سمعة الكورس سيئة وأن الناس متخوفيه منه وأن إمكانية القريد الطيب ليست مستحيلة ابدًا ) **\n.\nحط كل الكلام هذا عن الكورس هذا وتعال معي نشوف وش بتدرس أن شاء الله في هذا الكورس . بحاول أكتب كل المصطلحات باللغة العربية عشان تتذكرها اولًا من تجربتك السابقة في الثانوي + اذا حبيت تسترجع المعلومات وتبي تبحث عنها بالعربي اول.\n\nالتشابتر الأول : نقدر نقول تسخين وتجهيز العدة والعتاد للقتال في التشباتر الجاية, يعني مثلا تحويل الوحدات ومراجعة للأساسيات في الوحدات وتحويلها.\nالتشابتر الثاني: الحركة في إتجاه واحد , ومعادلات الحركة اذا كان التسارع ثابت . نفس الثانوي بالضبببط (بس لازم تتمرن عليها شوي لأنها بتتكر بالضبط في تشابتر 10).\nالتشابتر الثالث: المتجهات , أي بمعنى الحركة في اتجاهين مختلفين وممكن ثلاث اتجاهات . أخذنا عليها تشابتر كامل في ماث 002 ( vectors) . هذا التشابتر لازم تفهمه وتستوعبه وتتشرب كل المعلومات اللي فيه لأنه حجر الاساس في الحركة في عدة إتجاهات وبتحتاج التشابتر هذا كثييييييييييييير في التشباتر القادمة.\nالتشابتر الرابع: خذ تشابتر 2 و3 حطهم في الخلاط يطلع لك تشابتر4 + بعض المقتطفات من السرعة الدائرية والحركة النسبية\nالتشابتر الخامس والسادس : قوانين نيوتن الثلاثة+ التسارع الدائري للأجسام+ قوة الإحتكاك\nالتشابتر السابع : الطاقة الحركية والشغل الناتج عن الزنبرك وعن الجاذبية\nالتشابتر الثامن : نفس 7 بس زيادة عليه طاقة الوضع + الحالات اذا كان مجموع الطاقة الميكانيكة محفوظ أو فيه طاقة خارجية تؤثر على الجسم\nالتشابتر التاسع : مركز ثقل الأجسام + الزخم الخطي + الإصطدام بين جسمين أو أكثر.\nالتشابتر العاشر والحادي عشر : جميع ما سبق كان في حركة خطية أي مسار مستقيم والان يتغير كل شي ويصير حركة زاوية + عزم القصور الذاتي\nالتشابتر الثالث عشر : الجاذبية والكواكب في المجرة الشمسية والقوة بينهم.\nالتشابتر الرابع عشر : الموائع والضغط والكثافة .\nالتشابتر الخامس عشر والأخير : الحركة التذبذبية .\n.\nزي ما قريت معي عزيزي غالب التشباتر او نسبة كبيرة جدا منها موب أول مرة تسمع فيها, يعني قد مرت علينا في الثانوي وعندنا خلفية ولو بسيييطة عنها .\nاذا استعنت بالله وعطيت المادة حقها من المذاكرة والله العظيم اقدر اضمن لك A او +B ,ولا تزعل.\n\nوفقنا الله وإياكم ولا تنس أولا وخر عن كلام الناس ومذاكرة اول بأول الكورس يصير لك اسطوري", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/21", "user": "user10610", "ts": 1515988467000, "tid": 120502, "pn": 21}}', 1515988467000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1494537-phys101', 'stk-ahm2d1', 'PHYS 101', 'info', '{"desc": "Term 172\n\nالكورس بشكل عام وسط الى ثقيل شوي لانه يحتاج تدريب كثير كثير …\n\nبإختصار عشان تضبط وضعك ذاكر اول بأول وحل في الكحيلي لين تطفش وعليك بدفره زون وامورك باذن الله بتكون في السليم .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/22", "user": "Ahm2d1", "ts": 1529794202000, "tid": 120502, "pn": 22}}', 1529794202000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1507869-phys101', 'stk-bb_aa33', 'PHYS 101', 'info', '{"desc": "Term 181\n\nفيزكس 101 بالنسبة لي ماكانت تعجبني ككونسبت أصلا فعشان كذا كلامي هنا ممكن يختلف\n\nأنا من الاوريا كنت أسمع عن هذا الكورس وإنه القريد فيه صعر فأنا تحمست لهذا الكورس وقلت تحدي بالنسبة لي\n\nلكن صراحة يوم أخذت الكورس اكتشفت إنه منجد كان صعب وأسئلتهم نار\n\nطبعا هذي وجهة نظري وتختلف من طالب لطالب ثاني\n\nفيه طلاب أخذوا +A وفيه D\n\nلكن عموما لو واجهت صعوبة في هذا الكورس ترى شي طبيعي والديبارتمنت حابب هذا الشي أصلا ! آفرج المياجر لازم 50% يكون ولا راح يجيك فاينل منت متأكد غير من رقمك الجامعي!\n\nعموما أشوف Phy 102 أشوفه أسهل نسبيا من 101 لكن الديبارتمنت ماعليه أمان\n\nحتى لو خبصت فيه عندك فرصة تعوض قدام\n\nالحمد لله إننا تخارجنا من ذا الكورس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/24", "user": "bb_aa33", "ts": 1553610427000, "tid": 120502, "pn": 24}}', 1553610427000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1509302-phys101', 'stk-ad.99', 'PHYS 101', 'info', '{"desc": "term 182\nمحدثكم اخذ +ِA بالمادة هذي .\nلا تسمع لكلام اللى يقلك وحش الجبل او الكورس ذا صعب او او او , الكورس سهل ويتطلب تدريب مكثف وبتكتشف انه من امتع واسهل الكورسات اللى بتمر عليك\n+ ال +A تبدأ من 80 متخيلين كيف !!!\nالكونسبت سهل فهمه حتى بعض التشابتر تفهمها من الدكتور ما يحتاج تذاكرها من مصادر خارجية لكن اذا حبيت تستزيد فيه سلايدات الجلال جدا جميلة وتلخص لك افكار الدرس .\nاسئلة الكحيلي جدا جدا جدا جدا مهمه ولازم لازم تخلص عالاقل 70-75 بالمئه لكل تشابتر وافضل لك تخلصها كلها , اصلا لو خلصت 70 بالمئه بتكون مدرك جميع افكار التشابتر تقريبا ف ما اتوقع ال 30 الباقية بتكون صعبة عليك .\nالله يجزاه خير الدكتور الكحيلي مجمع اولد اقزام من 1999 الى 2014 بطريقة جدا جميلة ومرتبة ومقسمها لقسمين : مسائل واسئلة كونسبت .\nاذا أشكل عليك سوال وما عرفت تحله فيه عندك دفرة زون الله يجزاه خير , حال اسئلة الكحيلي لكل تشابتر وانتبه انتبه تتفرج على دفرة زون بدون م تكتب بيدك وتتمرن , خذ دفرة ك مرجع وليس كمصدر اساسي لان فية طلاب كثيرين ما يحلون ويشوفون دفرة زون ولا يجيبون درجات طيبة ويشتكون !! يالغالي هذي مادة فهم وليس حفظ او مشاهدة مقاطع وبس . ف زي ما قلت لكم لازم انت تحل بنفسك لكن اذا دقرت عند سؤال ما فيه مانع ترجع ل دفرة زون .\nفية طريقة انا كنت اسويها وكانت جدا فعالة يمكن بعضكم ما يحس ب أهميتها لكن كانت جدا مهمه بالنسبة اللى هي لاجيت احل اسئلة الكحيلي ابدأ من تحت مو من اول سوال , صحيح في البداية راح تواجه صعوبة لكن مجرد ما تبدأ تحل كمية لا بأس فيها من الاسئلة تجد ان فهمك تطور بشكل كبير. خلينا نقول ان التشابتر فية 50 ف لو بديت من تحت يمكن توصل سوال 30 وتحس انك فاهم مرة ل درجة ان ال 30 سوال المتبقية تلحها بسرعة وبعضها تحلها في مخك ف كانت طريقة جدا فعالة بالنسبة لي ايضا لا تنسى تحل اسئلة الكونسبت لانه في الميجر الثاني جابوا سوال نسخ لصق من الكحيلي .\nنصيحتي لك ب هالكورس انك تجمع درجات قبل لا تدخل الفاينل ب حسبة بسيطة خلينا نقول انك جبت بالميجر الاول 17 والثاني 17 واللاب 15 والكلاس وورك 8 بكذا يصير مجموعك 57 ويبقى لك على ال +A ولازم تجيبة بالفاينل 22 اذا كانت غياباتك اقل من 6 او 23 اذا كانت اكثر , حاول تجيب اكثرمن 57 لانه ما تضمن الفاينل زي ما حصل ب 181 كان افرجهم بالميجر الثاني مرتفع وجابوا لهم فاينل لا اله الا الله راح تلاحظوه لما تجون وتحلون اولد اقزام تجدوه مختلف جدا عن الفاينلات الثانية لكن لو كان افرجكم حول ال 50 راح يجيبون لكم فاينل معقول زي حق 182.\nبالختام\nنصيحتي لك لا تأجل شي في المادة ولا تراكمها لانه تقريبا كل تشابتر يعتمد على الثاني ف مهم جدا انك تكون فاهم التشابتر السابقة .\nايضا اعيد واكررها حاول قد ما تقدر تجمع درجات قبل الفاينل عشان تكون مرتاح وتعطي المواد الثانية حقها\nبعد في الفاينل ركز على تشابتر ما بعد الميجر الثاني لانها هي المهمه وعليها نسبة كبيرة من الاسئلة وحتى ماهي صعبة واسهل من ماتيريال الميجر الثاني , ممكن تشابتر 13 بيكون ثقيل شوي بس برضوا يبقى سهل ف لا تضيع التشابتر ذي وابدأ في مذاكرتهم اول شي في الفاينل بعدين راجع ماتيريال الميجر الاول والثاني , الاول بيكون سهل عليك تراجعة لانه سهل , الثاني تكون توك ما لك مدة طويلة مخلص الميجر الثاني ف بتكون فاهمه بس استرجاع معلومات .\nوبالتوفيق جميعا وفالكم ال +A .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/25", "user": "AD.99", "ts": 1556887182000, "tid": 120502, "pn": 25}}', 1556887182000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518636-phys101', 'stk-mr.power', 'PHYS 101', 'info', '{"desc": "بسم الله الرحمن الرحيم …\n\nكورس دسم فعلاً ولكن ليس بالصعب ، الكونسبت حقيقة متوسط إلى سهل ، ولكن الصعوبة فيه تكون بالاسئلة في الاختبارات ، لابد تكون فاهم الكونسبت ١٠٠٪؜ لتُجيب على الاسئلة ، غير ذلك لو تحل مليون اولد اقزام وأنت الكونسبت حقك مرتخي صدقني ماراح تأخذ الدرجة العالية أو المتوسطة اللي تبيها بالاختبارات …\n\nالكونسبت أولا وأخيراً في هالكورس خصوصاً …\n\nوفقكم الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/26", "user": "Mr.power", "ts": 1577939600000, "tid": 120502, "pn": 26}}', 1577939600000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1528502-phys101', 'stk-mohammed_alkalaf', 'PHYS 101', 'info', '{"desc": "ماراح اذكر شنو يغطي المقرر الاخوان الي فوق ماقصروا كفوا ووفوا … في البداية اذا نزلت هذا الكورس حط ببالك ثلاث نقاط\n١- المادة مو صعبة انما تحتاج منك جهد كبيييير\n٢- القريد فيها مو مستحيل بامكانك تطلع ب A+\n٣- لاتفكر انك تأجل مذاكرتها ، المادة عبارة عن١٥ شابتر يعني تقريبا كل اسبوع شابتر ف انت عليك كل اسبوع تنهي شابتر.\n\n-\n-\nبتكلم عن تجربتي في المادة في ترم ٢٠١ ولله الحمد طلعت بA+ في المادة … طبعا معروف انه مافي طريقة صح وطريقة خطأ للمذاكرة وممكن شخص يحتاج يحل ١٠ مسائل عشان يفهم وممكن شخص ثاني في مسألة وحدة يفهم بالمختصر يعني قد يكون الي سويته كافي وزيادة للبعض وقد يكون مو كافي ف انت شوف وش تحس يمشي معك وطبقه .\nفي البداية اذا كان دكتورك شرحه مو كويس لاتشيل هم عندك الاون لاين كورس شرحه فوق الممتاز وكثير يعتمد عليه … انا كنت ساحب على الدكتور وقت الكلاس واشوف الاون لاين كورسس\nبعد ماتخلص الاون لاين كورس افتح سلايدات الجلال ومر عليها … الان خلصت الكونسبت بشكل كامل هنا يبدا الشغل\n١ اولد الكحيلي\n٢ ريسايتيشن بابا\nالمجموع حوالي ١٠٠ سؤال لكل شابتر قسمها على الاسبوع كامل وباذن الله م بتخلصهم الا انت فاهم اغلب الشابتر وبتقدر تحل ف الاختبار وانت تضحك\n\nحاول يكون هدفك انك م تنقص ف الاختبارات ميد او فاينل لانه النظام في ٢٠١ صار كيرف والقريدات كلها ارتفعت على سبيل المثال\nA+ كانت ٨٠ واصبحت ٩٠ ف في فرق كبير بالدرجات بالاضافة الى نقصك ف درجات اللاب والكلاس وررك لانها افرج\n\nفي الاخير ، المادة ممتعة بس تحتاج جهدك عط المادة حقها وباذن الله بتطلع بقريد طيب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-general-physics-i/120502/29", "user": "mohammed_alkalaf", "ts": 1613229372000, "tid": 120502, "pn": 29}}', 1613229372000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p213363-phys101', 'stk-user2781', 'PHYS 101', 'info', '{"desc": "ما قصرت اخوي سلمان على النقل … والله يوفقك ويفقنا بالاختبارات …\n\nوتقبل مروري …\n\nحياك الله اخوي … جميع انشاء الله … شكراً على المرور 🙂\n\nللأسف\n\nما راح ينزل تشابتر 6\n\nسألت الدكتور اليوم وقال لي لأ\n\nبس ما قصّر\n\nالله يجزاه كل خير\n\nالظاهر لانه باقي ما كملة… اكيد راح ينزلة في وقت من الاوقات!\n\n------------------------------------------------------------------------------\n\nهذه إضافه\n\nRecitations\n\nRecitation Ch 4\nhttp://faculty.kfupm.edu.sa/phys/aljalal/Phys101-web/phys101-071-web/re-04.pps\nRecitation Ch 5\nhttp://faculty.kfupm.edu.sa/phys/aljalal/Phys101-web/phys101-071-web/re-05.pps\nRecitation Ch 6\nhttp://faculty.kfupm.edu.sa/phys/aljalal/Phys101-web/phys101-071-web/re-06.pps", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101/59343/14", "user": "user2781", "ts": 1193511997000, "tid": 59343, "pn": 14}}', 1193511997000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p357114-phys101', 'stk-user2154', 'PHYS 101', 'info', '{"desc": "http://ocw.mit.edu/OcwWeb/Physics/8-01Physics-IFall1999/VideoLectures/index.htm\n\n^^^^^^^^^^^^^^\nراح يفيدك بس تبي نصيحه الفيزكس مو بحل التمارين بالفهم ترا هو مو ماااث ذاكر الكتاب وشوف الفرق الله يستر من الفاينل ونطلع من دائرة الدي الى سي ان شا الله هههههههههههههههههههه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys101/69770/6", "user": "user2154", "ts": 1233117942000, "tid": 69770, "pn": 6}}', 1233117942000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p89297-phys101', 'stk-user1091', 'PHYS 101', 'info', '{"desc": "السلام عليكم\n\nالله يجزاك خير أخوي الفيروزي\n\nلكني أعترض معاك إن مذاكرة الكتاب تجيب الF\n\nأخوك فريشمان ذاكر الكتاب وذاكر نوت مكي ولاحظت الفرق\n\nمذاكرة الكتاب: أول شي ممتعة وبعدين تخليك تفهم أفكار الدروس\nوأنصح إخواني إذا بذاكرون الكتاب يمسكون كل برقراف ويقرونه ويحطون خط تحت الأشياء المهمة\n\nخلاص إذا رجعت بذاكر هذا البرقراف مرة ثانية ذاكر فقط ما تحته خط\n\nأما نوت مكي فأفضل شي تذاكره بعذ ما تفهم الفكرة (Concept)\n\n2- حل تمارين على قد ما تقدر\n\n3-أي شي ما تفهمه روح للمدرس في المكتب ولا تأجل\n\n4-بعض مدرسين الفيزياء ما يقصرون يسوون حصة تسمى help session يحلون يحلون فيها تمارين فحاول تحضرها\n\n5- حاول على قد ما تقدر تجي الحصة وإنت محضر الدرس الجديد\nوهذا التحضير راح تعرف قيمته في آخر الترم وبعد كل حصة\n\n6- في الكتاب في أمثلة تسمى Sample Problems حاول تعرف كيف طريقة الحل فيها\n\nالله يوفق الجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys101/49654/4", "user": "user1091", "ts": 1138827517000, "tid": 49654, "pn": 4}}', 1138827517000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p214239-phys101', 'stk-user2728', 'PHYS 101', 'info', '{"desc": "هلا شباب\n\nعبادي\nابو فواز\nفريشمان\n\nوالباقي اللي شاركوا في الموضوع\n\nشاكر لكم على هذي النصائح\n\nوان شاء الله نعوضها على خير في الاختبارات الجاية\n\n-----------------------------------------------------\n\nبس يا شباب\n\nوالله حرام\n\nاجازة العيد ما تهنيت فيها\nولا طلعت كثير مع الاهل والربع\n\nوقعدت اذاكر فيزياء\nومن الاربعاء اللي راح وانا قاعد اذاكر\nوكل اولد اكسام احله\nاجيب فيه تقريبا 15 من عشرين بدون لا اطالع السوليوشن\nوحليت تقريبا 6 اختبارات\n\nبس اخرتها نتفاجاء باسئلة مادري من وين جابوها\nوحتى اللي بياخذون فيزكس 101 الترم الجاي\nوبيحلون اولد اكسام\nراح يلاحظون ان اسئلتنا هي الاصعب\n\nوالله قهر\nعلى كل اللي ذاكرته\nوالوقت اللي راح علي\nاجيب في الاخير 9 من عشرين\nوالله حرااااااااااام\nوالله لو اني ما تعبت روحي وذاكرت بدال الفيزياء ماث ولا كيمياء كان اصرف من كذا\n\nااااااااااخ يالقهر\n\nولا تفكروني ابدردب\n\nاصلا انا ابي اعدي هالسمستر على خير\n\nبس نبي العباقرة اللي في ديبارتمنت الفيزياء يراعون كيف ان فيه 11 مدرس يدرسون هالمادة\n\nوكل مدرس له طريقته وخبرته في التدريس\nزي اغلب ربعي اللي خذوا عند رمضان وناصر واكسوي\nاغلبهم زفتوا\nوسكشنا ( ختك ) على الافرج\n\nيعني الصعوبة والسهولة تتراوح بين الطالب والمدرس للمعلومية\nوليست على الطالب نفسه\n\nتصدقون اني اسال ختك اسئلة ما عرفت احلها\nيقعد يهزئ فيني قدام الطلاب ويقولي انا عدت هالمعلومات اكثر من مرة\nوانت تتحمل كل هذا( this is your responsiblity )\n\nالله يعين\n\nبس ان شاء الله الميجر الثاني\nماني متعب روحي\nوراح اذاكر رؤوس اقلام\nوابدخل على الله\n\nعلى الاقل اذاكر ماث وكيمياء\nابرك من مقابل الفيزياء\n\nوالله يوفقنا واياكم في الاختبارات الجاية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101/59394/41", "user": "user2728", "ts": 1193792365000, "tid": 59394, "pn": 41}}', 1193792365000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p487434-phys101', 'stk-abdullah_al_shammari', 'PHYS 101', 'info', '{"desc": "يا عيال والله أني بنكبه\n\nمدرسنا الله يهديه ما يعرف يشرح زين ولا أفهم له\n\nالميجر أقزام يوم الاحد وأنا ماني فاهم شي غير تشابتر 1 و 2 << وهذي أول مره تصير لي أن الاختبار بعد كم يوم وأنا ما ذاكرت شي\n\nوأذا قرأت الكتاب تطلع لي طلاسم مدري من وين جايه << بالنسبه لطالب مستواه عادي بالانجلش\n\nوالنوتات جلال وغيرها ما تعطيك الفكره كامله بس رؤووس أقلام\n\nوأنا مستحي أروح عند الدكتور وأقوله أشرح لي تشابتر 4 و 5 و 6\n\nوش الحل يا شباب << ساعدوني … 😡", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys101/79778/1", "user": "Abdullah_Al_Shammari", "ts": 1257442490000, "tid": 79778, "pn": 1}}', 1257442490000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p332606-phys101', 'stk-hype', 'PHYS 101', 'info', '{"desc": "شباب أنصحكم نصيحة لله, انكم تطلعون على سلايدات د.جلال. أنا كان عندي التباس في بعض الفقرات, بس ما شاء الله الدكتور وضحها في السلايدات. وفيها كم سؤال تعطيك فكرة كيف تتعامل مع نوعيتها. http://faculty.kfupm.edu.sa/phys/aljalal/Phys101-web/phys101.htm\n\nأنا شايف انها أفادتني, فحبيت أبلغكم عنها. 🙂 والي دلنا عليها ,موضوع الأخ واصل http://skfupm.com/vb/showthread.php?t=25544 جزاه الله خير.\n\nوالله يوفق الجميع في الاختبار وان شاء الله نطلع منه ونحن منشرحين الصدر. أمين.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys101/67755/16", "user": "Hype", "ts": 1226684233000, "tid": 67755, "pn": 16}}', 1226684233000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p332623-phys101', 'stk-user2870', 'PHYS 101', 'info', '{"desc": "الله يوفقكم … 🙂\n\nأنتم توكلوا على الله و شدوا حيلكم و ما عليكم من المثبطين … اللي جايب D أو D+ غالبا ً بيقول\n\nالمادة صعبة … طالعوا المياجر القديمة وحلوها إن قدرتم ، أفكار الأسئلة محدودة جدا ً وما تخرج عن\n\nعنها … ( Rec الدكتور الجلال ممتازة جدا ً ) …\n\nفالكم الـ A+ 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys101/67755/17", "user": "user2870", "ts": 1226685853000, "tid": 67755, "pn": 17}}', 1226685853000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p201742-phys101', 'stk-3b_d_u_l_l_a_h', 'PHYS 101', 'info', '{"desc": "^\n^\nبالنسبة للماث انا مجرب نوت ايمن …\n\nممتاز من ناحية الترتيب والوضوح … كأنك تقرا من كتاب 🙂\n\nالامثلة عادية يبدا من السهل وبعضها من الكتاب ويتدرج بالصعوبة …\n\nاحسن شي فيه يحل بعض الاسئلة الصعبة من الكتاب (( اللي على نهاية التشابتر ))\n\nوفيه نوت المسلماني لكن ماادري عنه …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-note/58524/5", "user": "3b_d_u_l_l_a_h", "ts": 1189369045000, "tid": 58524, "pn": 5}}', 1189369045000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p202568-phys101', 'stk-war_criminal', 'PHYS 101', 'info', '{"desc": "يا شباب الفريشمن نصيحه لكم في كيفيه مذاكره الفيزياء بس قبل ما ابدأ لازم تعرفون ان الفيزياء سهله مره وفي عالم فيزيائي قال الفيزياء مستحيله الا اذا فهمتها فانها راح تكون تافهه والطريقه بسيطه\nاولا ركز مع الدكتور 100 % ولا تفوت اي نقطه\nثانيا خذ نوت الدكتور مكي ــ دام ظله ــ واقراه وافهمه علما ان هناك نوتين ( 2 نوت ) لمكي خذ اللي بخط الكمبيوتر اللي معها حل لاسئله مهمه واساسيه\nثالثا بعد نهايه كل شبتر خذ اسئله اختبارات قديمه وهذي الاسئله للدكتور نقفي الدكتور ما قصر مرتبها حسب الشباتر ومن عام 90 الى 62\n\nوانا اضمن للي يسوي كذا انه ياخذ اقل شئ A في الماده لان الاسئله حق الاختبارات قريبه من بعض.\nوختاما لا تنسون الدعاء \" اللهم ما سهل الا ما جعلته سهلا … \"\nمع تحياتي\nwar criminal", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-note/58524/8", "user": "war_criminal", "ts": 1189608980000, "tid": 58524, "pn": 8}}', 1189608980000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p921281-phys101', 'stk-user7729', 'PHYS 101', 'info', '{"desc": "وش هذا الإختبار ، و الله إني أذاكر أسبوع كامل و نص أجوبتي قس.\nعاد و لا سؤال الأجسام الثلاثة اللي جنب بعض ، جلست نص ساعة أحل فيه و ما عرفته ، انلحس مخي لدرجة إني البارح حلمان واحد صافقني كف على خدي اليسار\nقمت مفزوع أفكر وش مقدار القوة المؤثرة على خدي اليمين من الخد اليسار علماً بأن قوة الإحتكاك بين الضروس 0.2\nطبعا ما جلست أفكر على الفراش ، على طول قسيت الإجابة حتى خيارات ما في.\n\nالله المستعان ، الفيزكس حتى بالأحلام داخل .\n\nويش حال اللي عارف الاجابة وكان بيحطها لكن وسوس وحط اجابة خطأ\n\nالجواب الصحيح هو 2 تطلع التسارع تقسم القوة 9 على m1+m2+m3\nيطلع التسارع 2 تضربه في m3=1 تطلع القوة 2 N\n\nالاختبار كان سهل لكن الغباء والخوف وقلة التركيز 😭 😭 😭", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-major-1/114027/32", "user": "user7729", "ts": 1318930082000, "tid": 114027, "pn": 32}}', 1318930082000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1175904-phys101', 'stk-kinder', 'PHYS 101', 'info', '{"desc": "بسم الله الرحمن الرحيـم\nالسـلام عليكم ورحمة الله وبركاته …\n\n- من باب حب الخير للجميع , عندي نوت غير متوفره بالمكتبه ولا الجمعية تحتوي على جميع الاولد اقزامز مرتبه ليس فقط بالسكاشن وايضاً بالأفكار ! فمثلاً في ثاني تشابتر يعطيك جميع الاسئلة بدايةً من الافرج فيلوستي … ثم بعدها الاسئلة عن قوانين الكونستنت أكسليريشن , وبعدها جميع اسئلة الاولد اقزامز عن free fall وهكذا … بطريقة الحل و شرح للفكرة بطريقة رائعة جداً … !\n\nبصراحة , مذاكرة هالنوت وفهم الاسئلة اللي فيها كفيلة بجعلك تفهم أكثر من 80% من نوعيّة الاسئلة في أي إختبـار في هذا الكورس …\n\nالنوت يتكون من 250 صفحة , ما عندي إلا نسخة وحده تنتقل وراثيّاً : ) …\n\nاللي يبي نسخه يتفق معي على الخاص , أصوّرها له و نتلاقى في أي مبنى أكاديمي في وقت نحدده و ياخذها …\n\n🌺", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101/139795/1", "user": "Kinder", "ts": 1359912736000, "tid": 139795, "pn": 1}}', 1359912736000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p601394-phys101', 'stk-user4363', 'PHYS 101', 'info', '{"desc": "شباب انا شفت اسئلة واجب ch 10\nوصراحة كلها اسئلة سهلة واسئلة مياجر\nفيعني اذا كان صعب حلها فايش راح تسوون في الميجر ؟؟\nاتمنى انكم تحاولون حلها المرة هاذي\nواذا فيه سؤال صعب (مع اني ما اعتقد فيه) فانا موجود في الخدمة\nيعني كل الأسئلة تطبيق مباشر على القانون\n\nإيه بس ما اقدر يا فيزيائي عندي ميجرين كيمستري وفيزيكس والله ما عندي وقت اقعد عليه فلو تكرمت الله لا يهينك وراح ندعيلك ان على الاقل تضع أسئلة الهومورك اللي في الكتاب …\n\n😦", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101/82059/639", "user": "user4363", "ts": 1273240820000, "tid": 82059, "pn": 639}}', 1273240820000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p672654-phys101', 'stk-user6966', 'PHYS 101', 'info', '{"desc": "اخوي فيزيائي. انا تخصصي فيه خمس كورسات فيزكس . 101 و 102 و 201 و كورسين واحد elec.magnetic والثاني نسيته .\n\nوشكلي بحول من تخصصي إلى إدارة بسبب الفيزكس رغم اني راح ادرس فيزكس 101 بترم 0102 . يعني كل من عرف ان عندي خمس كورسات فيزكس أطلق ضحكة قوية وقال فكر بتخصص ثاني من الحين .\n\nكذلك ودي أعرف كل واحد من الكورسات أعلاه وش يتكلم عنه وشنو أصعب كورس فيزكس . وكيف أجيب قريد عالي في الفيزكس . قرأت موضوع مثبت هنا بس ما اقتنعت فيه عن طريقة مذاكرة الفيزكس .\n\nتقبل مروري", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101/82059/813", "user": "user6966", "ts": 1280735198000, "tid": 82059, "pn": 813}}', 1280735198000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p762668-phys101', 'stk-guest', 'PHYS 101', 'info', '{"desc": "اليوم وبكرة مخليهم للماث يا طويل العمر >>> ما فتحته من ميجر 2 😞\n12 خلصناه والحمدلله كل الاسئلة سهلة للي فاهم الشابتر صح\nالسبت نخلص 4 و 10 و 13\nالاحد 14\nالاثنين 9 و15\nالثلاثاء 11 ومراجعة للكورس كامل\nوبعدها استلم الاولد اقزام الباقية وصلى الله على محمد\nعسانا نطلع بقريد طيب 😆\n\nهذي الاسئلة من شابتر 7 و 8\n\nشابتر 7\n\n011 1\nAn object is constrained by a cord to move in a circular path of radius 0.5 m on a horizontal frictionless surface. The cord will break if its tension exceeds 16 N. What is the maximum kinetic energy the object can have? (Ans: 4.0 J)\n\n051 1\nA 0.50-kg block slides down a frictionless 30° incline, starting from rest. What is the work done by the net force on this block after sliding for 4.0 s? (Ans: 96 J)\n\n071 2 (موجود في الدليل)\nAn ideal spring is hung vertically from the ceiling. When a 2.0-kg mass hangs at rest from it, the spring is extended 6.0 cm from its relaxed length. A downward external force is now applied to the mass to extend the spring an additional 10 cm. While the spring is being extended by the external force, what is the work done by the spring? (Ans: −3.6 J)\n\nشابتر 8 اللي شكلي جايب العيد فيه 😦\n\nhttp://img708.imageshack.us/img708/4518/888r.png\n\n042 5\nA 6.0-kg box starts up a 30 degrees incline with 158 J of kinetic energy. How far will it slide up the incline if the coefficient of kinetic friction between box and incline is 0.40? (Ans: 3.2 m)\n\n022 6\nA 0.6-kg ball is suspended from the ceiling at the end of a 2.0-m string. As this ball swings, it has a speed of 4.0 m/s at the lowest point of its path. What maximum angle does the string make with the vertical as the ball swings? (Ans: 54)\n\n061 7\nAn object of mass m, attached to a light cord of length L, is held horizontally from a fixed support as shown in figure 2. The object is then released from rest. What is the tension force in the cord when the object is at the lowest point of its swing? (Ans: 3 mg)\n\n072 2\nA ball slides without friction around a loop-the-loop of radius R (see figure 3). The ball is released, from rest, at a height h from the left side of the loop. What is the ratio (h/R) so that the ball has a speed v = √Rg at the highest point of the loop? (Ans: 5/2)\n\n072 7\nA 0.50-kg block attached to an ideal spring with a spring constant of 80 N/m oscillates on a horizontal frictionless surface. The speed of the block is 0.50 m/s when the spring is stretched by 4.0 cm. What is the maximum speed the block can have? (Ans: 0.71 m/s)\n\n022 4\nA 12-kg block is resting on a horizontal frictionless surface. The block is attached to an un stretched spring (k = 800 N/m) (see figure 4). A force F = 80 N parallel to the surface is applied to the block. What is the speed of the block when it is displaced by 13 cm from its initial position? (Ans: 0.78 m/s)\n\n032 7\nA 0.50-kg block attached to a spring, with a spring constant of 100 N/m, moves on a horizontal surface having a coefficient of kinetic friction of 0.3 (see figure 7). The spring is initially compressed by 10 cm from the unstretched position O and then released from rest. What is the speed of the block when it passes through the point O? (Ans: 1.2 m/s)\n\nومثل ما قلت مهو شرط يحلهم الاخ فيزيائي لحاله\nالجميع يشارك ان شاء الله\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101/82059/1215", "user": "Guest", "ts": 1294924019000, "tid": 82059, "pn": 1215}}', 1294924019000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p954554-phys101', 'stk-user4631', 'PHYS 101', 'info', '{"desc": "الله يوفقكم يا شباب\n\nلكن اتمنى منكم التفكير قليلا\n\nلو افترضنا انكم تمكنتم من جمع جميع الريبورتات و الكوزز\n\nوكل الطلاب اخذته من المنتدى وحصلت على الدرجة الكاملة\n\nفما الفائدة من ذلك حيث انه في النهاية جميع طلاب هذا السكشن راح يحصلوا على 14 من 20\n\nوبالتالى هذه الحملة فيها مضرة لبعض الطلاب على حساب الاخرين\n\nالحمد لله هذا السمستر اخلص كورسات الفزكس لكن تذكرت هذه النقطة وحبيت اوضحها لكم\n\nو 102 يختلف من حيث انه رتن يعني لازم تسوي التجربة بنفسك وتعبي الريبورت بنفسك و الكوزز على المدرس\nو الفاينل لاب على كيف الدكتور برضوا\n\nاتمنى لكم التوفيق من كل قلبي وفالكم ال a+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-term-111/116207/44", "user": "user4631", "ts": 1325025686000, "tid": 116207, "pn": 44}}', 1325025686000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p954792-phys101', 'stk-user8496', 'PHYS 101', 'info', '{"desc": "الحل الصعب\n\nيعطيك العافيه يا صاحبي على حرصك\n🌹\n\nهمس الأفكار\nاعتقد ان مجمل كلامك هو عن سوء نظام الافرج , وهذا ما لا نختلف فيه\nوبالنسبه للمعادلة الدرجات مع الافرج بتكون عن طريق نسب وليست عشوائيه , مما يعني ان على قد جهد الطالب في الكوزز بيحصل افرج مرتفع , ولابات 101 ما فيها مذاكره اصلا , كلها شغل ساعتين بس\nتسلم على فكره “المساعده” , لكنها صعبه التطيبق , لأن اغلب الطلاب ما يشوف الريبورت إلا وقت الاب وبعض المدرسين لا يسمحون بفتح او بأستخدام مواقع خارجيه مثل skfupm , فأسهل طريقه هي لمن يشوف الطالب ريبورت جاهز صحيح 100% يعرف وش بيشتغل , وش القراف اللي يستخدمه , ماهي البيانات المطلوبه , وغيرها ,\n\nوشاكر لكم حرصكم وملاحظاتكم 🌹\n\nجاني على التقييم :\n\nوفي النهاية تنزل جميع الدرجات عشان الأفرج والناس اللي متعبة نفسها تاكل زفت والغشاشين ياخذون درجات … الله يسامحك\n\nاللهم اامين ,\nيا اخي “المجهول” محد ماكل زفت ولا شي ابد\nبالعكس كل الاطراف رابحه , طبعا انا ما قلت ان الهدف من الحمله هو نسخ الريبورت وتسويله سبمت كذا , هكذا بيضر الطالب نفسه …\nاللي نقصده بتجميع الريبورتات هو ان الطالب يكون عنده خلفيه عن الريبورت وعن المطلوب و كيفية المطلوب والشكل الافضل لأخراجه ,\nوشكرا لك على حرصك 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-term-111/116207/47", "user": "user8496", "ts": 1325078691000, "tid": 116207, "pn": 47}}', 1325078691000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p954901-phys101', 'stk-user8176', 'PHYS 101', 'info', '{"desc": "السلام عليكم\n\nهلا أخوي ولد المطر …\nيبدو إن هدفك جميل … لكن واقع الطلاب إللي ياخذون الريبورتات يسوون عكس إللي انت تقوله …\nيعني يسوون نسخ لصق … وما يدرون حتى وش هي التجربة …\n\nبالنسبة للكويزز … نفس الشي … الطلاب إللي لابهم يوم الأحد ياخذون الأسئلة من الناس إللي قبلهم وهكذا …\nالنتيجة … انه يصير عندنا أفرج عالي في الكلاس … ويقوم الدكتور ينزل جميع الطلاب …\nوالطالب إللي مجتهد ينزل مع بقية الطلاب … طيب تخيل طالب مجتهم وممشي حاله مو ذاك الزود ومجموع درجاته مثلا 14 من 20 … بعد ما ينزله الدكتور زي الطلاب كم ياخذ 11 أو 10 ؟؟!!\nالثلاث والأربع الدرجات هذي مين كان السبب في أن يفقدها … ؟؟؟\n\nنعم … نظام الأفرج نظام ظالم … لكن إذا ما كان بإمكاننا إننا نلغيه لا يعني أننا نتحايل عليه وفي النهاية نخسر كلنا …\nنظام الأفرج تماماً مثل : أن ترمي حب على مجموعة من الدجاج … ويتقاتلون عليه << أمزح !!\nأقصد إنه عندنا 400 درجة في الكلاس … والطلاب يتقسمونها … عاد تلحق ولا ما تلحق … هع\nوكل واحد ياخذ درجة تراه ياخذوها من أخوه إللي جمبه … وإذا صرنا ننسخ الريبورتات … راح نعطي ناس درجات ما يستاهلونها … وناس يستاهلوا الدرجات راح تروح عليهم …\n\nممكن فكرة تشوف الريبورتات تنفع في لابات غير الـ 101 لا أدري لإني ما أعرف … لكن ما يفعله الطلاب انهم نسخ ولصق … فقط\n\nهذا السبب هو اللي خلى حق اللاب حقنا ينقصني درجتين في الريبورت عشان ما حطيت وحدة القوة لفقرة واحدة فقط !!!!!! يعني حرف n !!!!!\n\nأخاف راح ينقصونا على : إنك لازم تبدأ بحرف كابتل في بداية الجملة … ولا راح ينقصك … !!\n\nالخلاصة وعذرا على الإطالة …\nالمسألة فيها ظلم لبعض الطلاب … وما تشوف انها \" غش \" صراحة ؟!\nيمكن انت تريد الطلاب فقط يأخذوا الفكرة … لكن الطلاب يغشوا يا صاحبي …\n\nالله يسعدك دنيا وآخرة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-term-111/116207/49", "user": "user8176", "ts": 1325090643000, "tid": 116207, "pn": 49}}', 1325090643000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p843047-phys101', 'stk-user5470', 'PHYS 101', 'info', '{"desc": "يعني لازم تفضحوني 😆 خلاص استروا علي ❤️ <<< 😆 😆 😆 مصدق الموقف و جالس يتخيل 😆\n\nعلى فكره الدكتور عبدالمنعم يوم قال ان فيه طالب واحد جاب 20 قلنا له من اي سكشن قال من سكاشن حيدر 🌹 و يقول ان الميجر الاول له بعد جاب 20 ما شاء الله عليه ❤️\n\nو قال لنا عن واحد جاب الميجر الأول 20 و الثاني 10 😆 يقول ازاي الكلام ده 🤪\n\nالله يستر من الفاينل … و الأفرج طايح مره بس الظاهر المدرسين متفقين ان يقولون للطلاب ان الأفرج حول 9 🤠", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-major-2-average/107200/13", "user": "user5470", "ts": 1305068615000, "tid": 107200, "pn": 13}}', 1305068615000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1410051-phys101', 'stk-user2352', 'PHYS 101', 'info', '{"desc": "مسائل محلولة بالخطوات مفيدة\n\nهذي مسائل محلولة مفيدة تشبه مسائل Recommended problems وهي من مسائل Tow points اغلبها مهم في فهم الكونسبت\nفي الكورس PHYS101\nhttp://dirac.phys.ncku.edu.tw/courses/genphys102-1/assign/index.php\n\nCH# 9\nhttp://www.uh.edu/~wkchu/courses/OLD/004/6094/homeworksolutions9.pdf\n\nhttp://www.uh.edu/~wkchu/courses/phys1321/chapter9/Home%20Work%209%20Solutions.pdf\n\nCH#10\nhttp://www.uh.edu/~wkchu/courses/phys1321/chapter10/Home%20Work%2010%20Solutions.pdf\n\nhttp://physics.usask.ca/~pywell/p121/assignments/Solutions-9.pdf\n\nCH#11\nhttp://www.uh.edu/~wkchu/courses/phys1321/chapter11/Home%20Work%2011%20Solutions.pdf\n\nhttp://www.uh.edu/~wkchu/courses/phys1321/chapter11/Reading%20Quiz%2011%20Solutions.pdf\n\nCH#12\nhttp://www.uh.edu/~wkchu/courses/phys1321/chapter12/Home%20Work%2012%20Solutions.pdf\n\nhttp://www.uccs.edu/~rtirado/Ch12%20ISM.pdf\n\nوهذا النوت للدكتور المبدع أحمد منصور الذي ترك الجامعة حاليا\nمن شابتر 7 إلى 15 نهاية الكورس وهذا النوت مبسط للكتاب ومحلول فيه مسائل وشرح للكونسبت أنصح بالرجوع له لمن اراد الفهم طلاب phys101\nhttp://www.mediafire.com/download/3t0io65nne61jl3/phys.rar", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys101-102/165979/18", "user": "user2352", "ts": 1415348244000, "tid": 165979, "pn": 18}}', 1415348244000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p849333-phys101', 'stk-kfupm_prince', 'PHYS 101', 'info', '{"desc": "بالنسبة لي صعب والله\n\nيعني ch 14 كل الأسئلة اللي جابوها تقريبا فيها نسب ؛ مافي سؤال طبيعي\n\n+\n\nالرموز ونسبة الـ rate كثروا منها صراحة >> عجبي ! احنا داخلين اختبار ماث ولا فزكس ؟\n\n+\n\nالشيء الأخير كثروا من أسئلة شابتر 15 كثيييير ؛ وللاسف هو الشابتر الوحيد اللي مافهمته أو ذاكرته عدل ؛ ايش ذنب اللي مثل حالتي ؟ خخخ\n\nالله يعين أهم شي إن شاء الله عدينا هالمادة الغثيثة …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-final/108042/19", "user": "KFuPM_PRinCe", "ts": 1307641037000, "tid": 108042, "pn": 19}}', 1307641037000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1409732-phys101', 'stk-eleven', 'PHYS 101', 'info', '{"desc": "فعلا اختبار صعب جدا , يعني مدري وش المفروض اسوي , حليت اولد اقزام ادهم من تشابتر 5ل8 مرتين وحليت اولد اكزام الكحيلي تشابتر 7و8 ونص 5و6 وذاكرت نوتات مدرسنا ونوتات جلال , وكل تشيك بوينت بالكتاب , وبالنهاية ماحليت الا 4 اسئلة والباقي قس , بس دام جبنا فوق الافرج اقول الحمد الله على كل حال .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/major-2-phys-101/166831/62", "user": "eleven", "ts": 1415211327000, "tid": 166831, "pn": 62}}', 1415211327000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p730395-phys101', 'stk-saleh_ali', 'PHYS 101', 'info', '{"desc": "الف مبروك للي جاب درجه عاليه و للي ما جاب اللي يبغى يشد حيله ويشوف وين الغلط\nولا اشوف رجال يحذف الماده منشان الدرجه تحت السته استمر وشد حيلك حتى لو حذفت بتأخذ الترم الجاي في ميجر ون عشره الى 13 لو شديت\nيعني خل الحذف يقعد و شد في ميجر تو والفاينل واللاب ولا تخلي هوم وورك ولا كوز الا وتذاكر له وتحله\n\nوعفاكم وطولة بقاكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101/97590/13", "user": "saleh_ali", "ts": 1288625703000, "tid": 97590, "pn": 13}}', 1288625703000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1261706-phys101', 'stk-dhomy_alzhrani', 'PHYS 101', 'info', '{"desc": "و الله أنا أشوف إن النوت مفيييد كبداية\n\nيعني كل الطلاب تقريبا من زمان عن الفزكس (الحقيقي)قصدي الثانوية … لان فزكس الاوريا كلام فاضي , لذلك النوت مهم في استرجاع المعلومات و طرق الحل و استخدام القوانين أما عند الميجر فـ(ما يوكل عيش) , لذلك يجب عليك أن تذاكر من أسئلة الكتاب و رستيشن الجلال فزكس , لان مستواهما مثل المياجر .\n\nولك كل الشكر يا روما c\n\n🙂\nدعواتكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys101/149177/4", "user": "Dhomy_alzhrani", "ts": 1378735364000, "tid": 149177, "pn": 4}}', 1378735364000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p900161-phys101', 'stk-physicist', 'PHYS 101', 'info', '{"desc": "في السؤال الأول, راح تستعمل طريقة التحويل\nراح تحول المتر الى ميل وتحول الثواني الى ساعات\nطبعا قيم التحويل ما راح يعطونه لك في الواجب، يبغالك تطلعها من آخر صفحة في الكتاب\nلكن في الاختبارات والمياجر، راح يعطونه لك\n\nفي السؤال الثاني، تجيب حجم المكعب اللي هو طول الضلع تكعيب\nالجواب راح يكون بالمتر المكعب، تحوله الى قدم مكعب باستعمال قوانين التحويل في آخر الكتاب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101/103414/271", "user": "Physicist", "ts": 1315861045000, "tid": 103414, "pn": 271}}', 1315861045000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1457856-phys101', 'stk-electricalism', 'PHYS 101', 'info', '{"desc": "السلام عليكم و رحمة الله و بركاته 🤠\n\nارحب بكم يا معشر ال Phys101 العظيم 😁2:\n\nأخوكم في الله توه متخرج و فااااضي 👏، و بسبب الفضاوة الزايدة قررت أحل اسئلة د.الكحيلي لمادة Phys101 وارفعها على يوتيوب. انتهيت من تصوير الاربع الشباتر الأولى لكن للأسف حذفتها 😞. بعد التصوير شغلت الفيديوهات و اكتشفت ان الشرح كان مو بالمستوى الجيد 😆.\nهذي صورة للكارثة بعد حل اربع شباتر 😆\n\nhttp://f.top4top.net/p_261whuz1.jpg\n\nأعدت التصوير بجودة أفضل من ناحية الشرح و الصوت و كل شي و انتهيت من تشابتر 1 😆. الشباتر الباقية رح اصورها وارفعها بمعدل شابتر لكل اسبوع بالاسابيع الجاية\nهذا رابط التشابتر الاول https://goo.gl/ag92Nr\n\nللي ما يعرف اسئلة الكحيلي، أسئلة الكحيلي هي اسئلة أولد اكزامز مجمعة تشابتر باي تشابتر، اذا حليتها كاملة لكل تشابتر قبل الميجر تقدر تضمن فل مارك!\nتقدر تحملها من موقع الدكتور Kuhaili_General_Physics_PHYS 101_ Old_Exams\n\nراح اقول لكم افضل طريقة لمذاكرة هذي المادة (من وجهة نظري طبعا 😆)\nالطريقة هذي نفعت معي و الحمدلله قدرت اطلع من الكورس بـ A+\n\nأولاً: لازم تصير مذاكرتك على شابتر شابتر، ما ينفع انك تذاكر الماتيريال حق الميجر كامل بعدين تبدا تحل اولد اكزامز لأن الشي هذا رح يشتت تفكيرك و راح يخلي المعلومات تتداخل مع بعضها.\n\nثانياً: ما ينفع تذاكر من الكتاب 😆\nالنقطة ذي يمكن كثير يخالفني الرأي فيها لكنها حقيقة. لما تقول لواحد حل اسئلة الكتاب عشان تستعد للميجر كأنك تقول لواحد تعلم كيف تسوق تريلة عشان تسوق سيارة.أتوقع شيء جدا بديهي إنه عشان تستعد للميجر لازم تحل ميجر 😆. يعني لازم تحل اولد اكزامز.\nاسئلة الكتاب طريقتها مختلفة عن اسئلة المياجر، في الغالب اسئلة الكتاب معقدة جدا و تاخذ وقت كثير بدون فايدة.\n\nثالثاً: افهم الماتيريال\nبالنسبة للماتيريال في عدة مصادر تقدر تستخدمها . أفضلها على الإطلاق هي سلايدات د.الجلال، السلايدات هذي صراحة تغنيك عن الكلاسات. بدون منازع هي افضل سلايدات مرت علي بالجامعة 😆. في برضو مصدر ثاني اللي هو فيديوهات د.سالم و د.مكي في البلاك بورد، هذي جديدة و ما كانت موجودة على ايام ما كنت منزل الفيزيكس بس من كلام الطلاب انها جدا مفيدة لفهم الماتيريال.\nنصحية لا تحط اكثر من اربع ساعات على ماتيريال التشابتر الواحد. حاول انك تاخذ الزبدة و تخش ع الاسئلة. في اشياء تحسها زايدة وما تقدر تفهمها الا اذا حليت عليها سؤال. راح تستفيد من وقتك اكثر اذا حطيته على الاسئلة\n\nرابعاً: حل اسئلة د.الكحيلي 🥊\nالدكتور مجمع حوالي 50 الى 100 سؤال اولد اكزامز على كل تشابتر. منظمة بشكل جدا جميل، طبعا انت ما تحتاج تحلها كلها. سويت التقسيمة هذي واتوقع انها قريبة من الواقع\n\nاذا تبغى A+ لازم تحل اكثر من 75% من اسئلة د.الكحيلي\nاذا تبغى A لازم تحل اكثر من 65% من اسئلة د.الكحيلي\nاذا تبغى B+ لازم تحل اكثر من 45% من اسئلة د.الكحيلي\nاذا تبغى B لازم تحل اكثر من 35% من اسئلة د.الكحيلي\nاذا تبغى C+لازم تحل اكثر من 20% من اسئلة د.الكحيلي\nاذا تبغى C أو D أو D+ افهم الماتيريال فقط بدون حل اسئلة\nاذا تبغى F لا تذاكر شي 😆\n\nهذي مجرد توقعات 🚬 ، مافي اي دراسة تمت على النسب اللي فوق، لاحد يجيني اخر الترم يقول ليه ما جبت A+ 😆\nالتوقعات اللي فوق للشخص الي يذاكر اسبوعيا، اذا كنت من النوع اللي يذاكر قبل الميجر زود النسب كلها 20% 🤣\nسبب الفرق بين اللي يذاكر اسبوعيا و اللي يذاكر قبل الميجر هي إن الشخص اللي يذاكر اسبوعيا راح يضمن درجات الكويزات و اللاب و الهوموورك. اما اللي يذاكر قبل الميجر راح يضيع ذي كلها و لازم يعوض بدرجة عالية بالميجر.\nانا كنت من النوع اللي يذاكر قبل الميجر و كنت احل كل اسئلة د.الكحيلي و ضبط الوضع معي 👍\n\nخامساً: حل الأسئلة بنفسك، لا تشوف الجواب على طول، اذا قعدت في السؤال اكثر من خمس دقايق ولا وصلت للجواب شوف الفيديوهات و ان شاء الله تفيدك.\n\nبعض المعلومات عن الفيديوهات:\n1- في بداية الفيديو تقدر تنقز للسؤال اللي تبغاه بمجرد الضغط على السؤال. اذا ما ضبطت معك فعل الannotations. تقدر تنزل للديسكربشن ايضا فيه توقيت كل سؤال. اضغط ع التوقيت و راح تنقز للسؤال مباشرة.\n2- الاسئلة مطبوعة على ورق و ما راح تكون واضحة الا اذا حطيت الفيديو على جودة 1080p او 720p .\n3-اعذروني على كلمة OK بفيديو الشابتر الأول. قلت ok مليون مرة 😡\n3- اسئلة الدكتور الكحيلي مقسمة على حسب المفاهيم. و كل مفهوم يكون له شكل. اذا حملت الملف راح تفهم قصدي. أنا اركز على السؤال الأول لكل مفهوم و افصل فيه زيادة. الاسئلة الثانية من نفس المفهوم احلها بشكل واضح ولكن ما افصل فيها نفس ما افصل بالسؤال الأول من كل مفهوم. الاسئلة ذي اذكرها بمقدمة الفيديو.\n4- اخذت بعين الاعتبار ان الشخص اللي يشوف سؤال معين مو بالضرورة يكون مر على الاسئلة الي قبل كلها. ولذلك احيانا اكرر الكلام في اسئلة كثير. اذا تابعت الفيديو كامل و شفت كل الأسئلة راح يكون ممل بالنسبة لك بسبب كثرة تكرار شرح المفهوم بكل سؤال.\n5- اذا عندك اي سؤال تقدر تكتبه بالتعليقات تحت الفيديو و راح اكون متواجد ان شاء الله خصوصا قبل المياجر. تعليقك راح يفيد غيرك من الناس اللي عندها نفس السؤال.\n6- اذا انت دافور ساعدني بالرد على التعليقات وقت المياجر 😂\n7- اذا فجأة سحبت بنص السمستر اعرف اني لقيت وظيفة 😆 😆\n8- اتمنى ان يحوز هذا العمل على رضاكم و اتمنى يفيد اكبر شريحة من الطلاب ،إن شاء الله اتوفق بتوصيل المعلومة و اذا عندك اي اقتراح لطريقة الشرح او الفيديو او اي شي تقدر تتواصل معي على ايميل الجامعة s201193750\n\nأتمنى لكم سمستراً مثمراً 👋", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys101/174688/1", "user": "Electricalism", "ts": 1474184149000, "tid": 174688, "pn": 1}}', 1474184149000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1001955-phys101', 'stk-_slow', 'PHYS 101', 'info', '{"desc": "خذ العلم الاكيد الافرج بيكون فوق 11\n\nانا واحد عايد المادة صراحه اقل مايقال عنه سهلللللل\nلية لاتسئلني مو مذاكر ذيك المذاكره لكن النفسية لها دوووووور\nالحمدلله كنت مبسوط ع الاخر وقول في نفسي هذي ثاني مره اخذ المادة وفاهمها زين\nباقي النتيجة نشوف ايش يصير …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-phys-101/122464/3", "user": "_Slow", "ts": 1331057302000, "tid": 122464, "pn": 3}}', 1331057302000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1002012-phys101', 'stk-fox_eye', 'PHYS 101', 'info', '{"desc": "الآفرج بين 19.5 و 20 👍******\n\n**بالتوفيق للجميع الاآختبار سهل جدا والفل مارك بالراحه للي ذاكر وفاهم بشكل عام **\n\n**ـٍ **انا معيد الماده وجدا كان بالنسبه لي سهل ورفع من معنوياتي جدااا والحين متحمس وبذاكر للميجر 2 لانه بيجي :sneezing_face: *للغايه ٍـ بس انشالله في امل يكون في *سهووله الاختبار هذا\n\n**فال الجميع الفل مارك وانشالله ميجر 1 لكورس 102 يكون سهل مثل اختبارنا ـ **\n\nموفقين 🌹******", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-phys-101/122464/6", "user": "fox_eye", "ts": 1331061683000, "tid": 122464, "pn": 6}}', 1331061683000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1171087-phys101', 'stk-mysterious', 'PHYS 101', 'info', '{"desc": "الهوموورك والكلاس وورك عليها 10درجات , المفروض درجتك ما تقل عن 9 أو 8.5 لأنه حسافة تنقص فيهم وسهلة إنّك تجيب الدرجة المذكورة ,\n\nمصادر مهمّة للمذاكرة , أول شيء تقرأ الماتيريل من الكتاب وتفهم وش صاير في الشابتر ,\n\nأولد إقزام الكحيلي ( وإذا ما قدرت عليها ذاكر أولد كوزز الكحيلي المحلولة , مفيدة جداً )\n\nالأولد إقزام الكاملة الموجودة في موقع الفزكس أو الجمعية , ( تعطيك فكرة كيف شكل الاختبار وتوزيع الأسئلة وهكذا )\n\nوبالتوفيـق جميعاً , 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys101/138899/9", "user": "Mysterious", "ts": 1359308628000, "tid": 138899, "pn": 9}}', 1359308628000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1105043-phys101', 'stk-convictim', 'PHYS 101', 'info', '{"desc": "كلامك صحيح 100% ما ادري وش فيهم عطونا ذي الاسئلة, بدون مبالغة اتوقع حتى نيوتن نفسه موب عارف يحلها 😞.\nكان تفكيري اني اخذ قريد حلو في الفزكس, لكن بعد النتيجة والله اني خايف من الـ f.\nالحين النفسية زفت وبعد كم ساعة عندي ميجر ومخي قفل.\nيارب ان تتسهل ويصير الميجر الجاي والفاينل سهلة نعوض ونعديها على خير …, قولوا امين.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-phys-101/133255/49", "user": "CONVICTIM", "ts": 1349703997000, "tid": 133255, "pn": 49}}', 1349703997000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1105089-phys101', 'stk-a_dulaziz', 'PHYS 101', 'info', '{"desc": "صدقني هذا نظام الماده الكريه تحل أولد أقزام\nبالنهايه تشوف أختبار جديد\n\nالي يحطون الأختبار شرط ما يكونون يدرسون المادة دائما يعني هذا الميجر مو حاله خاصه\n\nوبعدين ترى الأسئلة مو من كتابته ياخذونها من أماكن ثانيه أذا تبي دليل أنسخ سؤال وأبحث عنه بالنت بعضها تحصلها وبعضها لا\n\nعندكم بالاب 20 تقدرون تجيبون فيه من 14 - 18\n\nالهوم ورك حرام أحد ياخذ أقل من 3ونص من 5\n\nالكلاس ورك الي يشد حيله ياخذ 3 أو يمكن 4\n\nالي ما يذاكر ياخذ 2ونص\n\nهذي أشياء اساسيه لازم تتجمع\n\nاما المياجر كل واحد يدرس الي يقدر عليه والتوفيق من الله للعلم ترى a+ بالميجر 16\n\nشدو حيلكم من الحين ترى الميجر الجاي أصعب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-phys-101/133255/54", "user": "A_DULAZIZ", "ts": 1349708259000, "tid": 133255, "pn": 54}}', 1349708259000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1105191-phys101', 'stk-a.atiq', 'PHYS 101', 'info', '{"desc": "استعدوا للميجر الثاني يا اخواني الفضلاء يقولون ان الميجر اللي فات اسهل ميجر فيزكس بيمر علينا\n\nما أخوفكم … لكن أبلغكم … عشان تشدون حيلكم\n\nأتذكر في الأوريا في ماث 001 جبت في الميجر الأول 9 وجاني نفسية ما يعلم بها الا الله\n\nقالوا لي الميجر الثاني صعب ومدري ايش\n\nجبت 18 الحمدلله\n\nنفس الكلام في 002\n\nقالوا الميجر الثاني كله قوانين ومعقد ووو\nجبت 19 الحمدلله\n\nفيوجد بعض الأمل عندي بالعوض في الميجر الثاني ان شاء الله\n\nتوكلوا على الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-phys-101/133255/56", "user": "A.Atiq", "ts": 1349721166000, "tid": 133255, "pn": 56}}', 1349721166000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p492022-phys101', 'stk-user2040', 'PHYS 101', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nياشباب انا منزل الاب للفيزكس 101 عند الدكتور فؤاد عناية وبصراحه الاب عنده مرره صعب\nوتصحيحه للريبورتات دقيق مرررره يعني بالعربي ما تجيب عنده درجات عدله\nومعظم الي في الكلاس ما يخلصو الريبورت الا على آخر عشرة دقايق لان الشرح مختصر جدا جدا\nفأتمنى من الي عنده ريبورتات سابقة لهالمادة ينزلها هنا او يراسلني على الخاص\nعلى الاقل الواحد يقدر يعرف كيف يسوي الريبورت قبل الكلاس\nومشكووورين مقدما\n\nتحياتي لكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/i-need-phys-101-lab-reports/80073/1", "user": "user2040", "ts": 1258059539000, "tid": 80073, "pn": 1}}', 1258059539000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p565461-phys101', 'stk-user4260', 'PHYS 101', 'info', '{"desc": "السلام عليكم …\n\nاتمنى الجميع بخير وصحة .\n\nياشباب هذي خدمة بسيطة وقليلة بحق الشباب هنا واللي يسوونه عشانّا …\n\nهذا Study Guide رفعته لكم على موقع zShare بحكم إنه موقع سريع وخفيف … الملف كبير شوي لكن يستاهل والله … ما اكذب عليكم سهل علي فوق 80% من المفاهيم والمنهج كله !! بالبداية كنت أحس اني مشوش وماني عارف وش الطبخة , قمت اقرا فيه واستفدت استفادة عظيمة … اسلوبه حلو وبسيط ويعطيك امثلة على كل تشابتر ويشرحها لك بطريقة مدرس وطالب يتحدثون لبعض .\n\nhttp://www.zshare.net/download/7369303255966b2a/\n\nواللي يبي المانوال برضو يقولي ارفعه لكم …\n\nدعواتكم بس , قربت المياجر 😦", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/phys-101-study-guide-101/85376/1", "user": "user4260", "ts": 1268567445000, "tid": 85376, "pn": 1}}', 1268567445000, 1794826873, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
